import{_ as o,C as n,o as i,c as s,j as t,a as r,E as d,a4 as c}from"./chunks/framework.zh2mtvcP.js";const w=JSON.parse('{"title":"Son of a Tailor","description":"","frontmatter":{},"headers":[],"relativePath":"competitors/son-of-a-tailor.md","filePath":"competitors/son-of-a-tailor.md","lastUpdated":1794245099000}'),l={name:"competitors/son-of-a-tailor.md"};function h(p,e,u,f,m,g){const a=n("AudioBrief");return i(),s("div",null,[e[0]||(e[0]=t("h1",{id:"son-of-a-tailor",tabindex:"-1"},[r("Son of a Tailor "),t("a",{class:"header-anchor",href:"#son-of-a-tailor","aria-label":'Permalink to "Son of a Tailor"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"Angle:"),r(" custom fit and made-to-order production · "),t("strong",null,"Market:"),r(" USD storefront · "),t("strong",null,"Reviewed:"),r(" November 9, 2026")],-1)),d(a,{name:"son-of-a-tailor"}),e[2]||(e[2]=c('<h2 id="the-offer" tabindex="-1">The offer <a class="header-anchor" href="#the-offer" aria-label="Permalink to &quot;The offer&quot;">​</a></h2><p>The brand calls its cotton T-shirt its first product. Today the range also includes polos, shirts, and knitwear: a T-shirt-led specialist that has expanded, not a single-product business. <a href="https://www.sonofatailor.com/product/cotton-t-shirt/1-1-3-9-1" target="_blank" rel="noreferrer">Product</a> · <a href="https://www.sonofatailor.com/" target="_blank" rel="noreferrer">Current assortment</a>.</p><table tabindex="0"><thead><tr><th>White T-shirt</th><th>Observed details</th></tr></thead><tbody><tr><td>Product</td><td>Cotton T-Shirt, Medium Weight, White</td></tr><tr><td>Single-shirt price</td><td>US$75; bundle promotion shown separately</td></tr><tr><td>Fabric</td><td>100% Supima cotton; 150 GSM jersey</td></tr><tr><td>Fit &amp; production</td><td>Custom and standard sizes; made to order in Portugal</td></tr><tr><td>Timing &amp; shipping</td><td>7–10 days production; free shipping on two or more items</td></tr><tr><td>Fit assurance</td><td>Free remake if dissatisfied with the fit of the first order</td></tr></tbody></table><p>Source: <a href="https://www.sonofatailor.com/product/cotton-t-shirt/1-1-3-9-1" target="_blank" rel="noreferrer">product page, including Shipping and Guarantee tabs</a>. Production time is not delivery time. Single-item shipping, taxes, and refund conditions were not verified. A remake guarantee should not be treated as a refund policy.</p><h2 id="the-brand" tabindex="-1">The brand <a class="header-anchor" href="#the-brand" aria-label="Permalink to &quot;The brand&quot;">​</a></h2><p>Fit is the central promise, supported by material and production explanations. The page explicitly notes slight translucency in the white tee. <strong>Interpretation:</strong> customization and fit assurance reduce purchase uncertainty; production detail supports credibility. These are observed messaging choices, not proof of conversion effectiveness.</p><h2 id="archetype-persuasiveness" tabindex="-1">Archetypes &amp; persuasion <a class="header-anchor" href="#archetype-persuasiveness" aria-label="Permalink to &quot;Archetypes &amp; persuasion {#archetype-persuasiveness}&quot;">​</a></h2><p><strong>Tentative archetype: Creator, with Sage cues.</strong> Making a garment around the wearer suggests craftsmanship and individuality. The sizing explanation adds expertise. This is our interpretation of the <a href="https://www.sonofatailor.com/our-mission" target="_blank" rel="noreferrer">mission and sizing process</a>, not a declared brand identity.</p><table tabindex="0"><thead><tr><th>Lens</th><th>Observed evidence</th><th>Interpretation and limit</th></tr></thead><tbody><tr><td>Authority</td><td>Named production facility and partner expertise on the <a href="https://www.sonofatailor.com/our-production" target="_blank" rel="noreferrer">production page</a></td><td>Concrete production knowledge supports credibility; the brand’s claims still need independent checks.</td></tr><tr><td>Social proof</td><td>Trustpilot reference displayed on the <a href="https://www.sonofatailor.com/product/cotton-t-shirt/1-1-3-9-1" target="_blank" rel="noreferrer">tee page</a></td><td>A review signal, not proof about this exact white variant.</td></tr><tr><td>Risk reduction — outside the seven</td><td>First-order fit remake offered on the <a href="https://www.sonofatailor.com/product/cotton-t-shirt/1-1-3-9-1" target="_blank" rel="noreferrer">tee page</a></td><td>Addresses uncertainty about fit; it is not automatically reciprocity.</td></tr></tbody></table><p><strong>For our tee:</strong> test whether a simple fit guide provides enough reassurance before pursuing custom manufacturing. Personalization alone does not demonstrate commitment/consistency. <a href="/white-tee-research/research/brand-strategy.html">Framework and comparison</a>.</p><h2 id="customer-evidence" tabindex="-1">Customer evidence <a class="header-anchor" href="#customer-evidence" aria-label="Permalink to &quot;Customer evidence&quot;">​</a></h2><p>The product page displayed a Trustpilot reference of <strong>4.6/5 from 2,638 reviews</strong>. We did not independently inspect those reviews, so we cannot summarize recurring praise or complaints or assume the score concerns this SKU. <a href="https://www.sonofatailor.com/product/cotton-t-shirt/1-1-3-9-1" target="_blank" rel="noreferrer">Displayed review reference</a>.</p><h2 id="what-we-can-learn" tabindex="-1">What we can learn <a class="header-anchor" href="#what-we-can-learn" aria-label="Permalink to &quot;What we can learn&quot;">​</a></h2><p><strong>Takeaway:</strong> fit can be the product’s main differentiator; disclose material tradeoffs clearly. <strong>Test:</strong> willingness to wait for custom fit versus immediate shipping. <strong>Unknown:</strong> independent customer experience, full refund terms, and whether the white fabric’s translucency fits our intended use.</p>',14))])}const y=o(l,[["render",h]]);export{w as __pageData,y as default};
